void detach_mounts_from_dentry(struct dentry *dentry) {
    struct mountpoint *mnt;
    struct hlist_node *node;
    struct mount *p;

    lock_mount_namespace();
    mnt = lookup_mountpoint(dentry);
    if (mnt) {
        spin_lock(&mount_hash_lock);
        hlist_for_each_entry_safe(p, node, &mnt->mnt_hash, mnt_hash) {
            if (p->mnt_flags & MNT_UMOUNT) {
                unmount_child_mounts(p);
                list_add(&p->mnt_list, &unmounted_mounts);
            } else {
                unmount_mount_tree(p);
            }
        }
        spin_unlock(&mount_hash_lock);
        release_mountpoint(mnt);
    }
    unlock_mount_namespace();
}

void detach_mounts(struct dentry *dentry) {
    struct mount *mnt;
    struct hlist_node *node;
    struct list_head unmounted_mounts;

    lock_namespace();
    mnt = lookup_mount(dentry);
    if (!mnt)
        return;

    lock_mount_hash();
    INIT_LIST_HEAD(&unmounted_mounts);

    hlist_for_each_entry_safe(mnt, node, &mnt->mnt_hash, mnt_hash_entry) {
        if (mnt->flags & MNT_UNMOUNT) {
            unmount_child_mounts(mnt);
            list_add_tail(&mnt->unmounted_list, &unmounted_mounts);
        } else {
            unmount_mount_tree(mnt);
        }
    }

    unlock_mount_hash();
    release_mount(mnt);
    unlock_namespace();
}

